// priority: 0
// Chop's Spooktacular quest rework: Town Charter building checks and the other scripted quest tasks.
// Task ids come from spooktacular_quests_data.js (generated by the quest build script).
//
// How a building check works: the quest gives the player that building's Town Charter. They place it on the
// blueprint's anchor (middle of the front path) while facing the door. Every few seconds, while a player is
// near, this compares the real blocks with the blueprint's block list (kubejs/data/spooktacular/blueprints),
// a slice at a time so no single tick does much work. At SPOOK_MATCH the task completes.

const SPOOK_MATCH = 90            // percent of checked blocks that must match
const SPOOK_SLICE = 1500          // blocks compared per check
const SPOOK_RANGE = 128           // a player must be this close to the Charter for checks to run
const SpookBlockPos = Java.loadClass('net.minecraft.core.BlockPos')

const spookBlueprints = {}        // key -> {palette, blocks}
const spookScan = {}              // key -> scan state {pos, i, good, total, wrong[], pct}

function spookBlueprint(key) {
  if (!spookBlueprints[key]) {
    let data = JsonIO.read('kubejs/data/spooktacular/blueprints/' + key + '.json')
    if (!data) return null
    // copy into plain JS arrays once; reading Java lists block by block is slow
    let palette = [], blocks = []
    data.palette.forEach(id => palette.push(String(id)))
    data.blocks.forEach(b => blocks.push([Number(b[0]), Number(b[1]), Number(b[2]), Number(b[3])]))
    spookBlueprints[key] = { palette: palette, blocks: blocks }
  }
  return spookBlueprints[key]
}

function spookCharters(server) {
  if (!server.persistentData.contains('spookCharters')) server.persistentData.put('spookCharters', {})
  return server.persistentData.getCompound('spookCharters')
}

// Blueprint frame: building lies toward -z from the anchor. The player faced the door when placing,
// so blueprint "north" maps onto the facing they had.
function spookRotate(dx, dz, facing) {
  switch (facing) {
    case 'east': return [-dz, dx]
    case 'south': return [-dx, -dz]
    case 'west': return [dz, -dx]
    default: return [dx, dz]
  }
}

// Dimension id like "minecraft:overworld". (String(level.dimension) gives "ResourceKey[minecraft:dimension / ...]".)
function spookDim(level) {
  let s = String(level.dimension)
  let m = s.match(/\/ ([^\]]+)\]/)
  return m ? m[1].trim() : s
}

function spookCharterKey(blockId) {
  return blockId.startsWith('spooktacular:charter_') ? blockId.substring('spooktacular:charter_'.length) : null
}

BlockEvents.placed(event => {
  let key = spookCharterKey(event.block.id)
  if (!key || !event.player) return
  let facing = String(event.player.horizontalFacing.serializedName)
  let tag = {}
  tag.x = event.block.x; tag.y = event.block.y; tag.z = event.block.z
  tag.dim = spookDim(event.level); tag.facing = facing
  spookCharters(event.server).put(key, tag)
  delete spookScan[key]
  event.player.tell(Text.gold('Town Charter placed for ' + global.SPOOK_CHARTERS[key] + '.').append(Text.gray(' Facing ' + facing + '. Build from the blueprint; the quest checks it while you are near.')))
})

BlockEvents.broken(event => {
  let key = spookCharterKey(event.block.id)
  if (!key) return
  let charters = spookCharters(event.server)
  let c = charters.getCompound(key)
  if (c && c.getInt('x') == event.block.x && c.getInt('y') == event.block.y && c.getInt('z') == event.block.z) {
    charters.remove(key)
    delete spookScan[key]
  }
})

// Compares one slice of the blueprint. Returns the finished match percentage when a full pass ends, else -1.
function spookScanSlice(server, key) {
  let bp = spookBlueprint(key)
  let c = spookCharters(server).getCompound(key)
  if (!bp || !c || !c.contains('x')) return -1
  let level = server.getLevel(c.getString('dim'))
  if (!level) return -1
  let s = spookScan[key]
  if (!s || s.i >= bp.blocks.length) s = spookScan[key] = { i: 0, good: 0, total: 0, wrong: [], pct: s ? s.pct : -1 }
  let ax = c.getInt('x'), ay = c.getInt('y'), az = c.getInt('z'), facing = c.getString('facing')
  let end = Math.min(bp.blocks.length, s.i + SPOOK_SLICE)
  for (; s.i < end; s.i++) {
    let b = bp.blocks[s.i]
    let r = spookRotate(b[0], b[2], facing)
    let x = ax + r[0], y = ay + b[1], z = az + r[1]
    if (!level.isLoaded(new SpookBlockPos(x, y, z))) continue
    s.total++
    if (String(level.getBlock(x, y, z).id) == bp.palette[b[3]]) s.good++
    else if (s.wrong.length < 200) s.wrong.push([x, y, z])
  }
  if (s.i >= bp.blocks.length) {
    s.pct = s.total == 0 ? 0 : Math.floor(100 * s.good / bp.blocks.length)
    s.lastWrong = s.wrong
    s.lastOff = bp.blocks.length - s.good
    return s.pct
  }
  return -1
}

function spookNear(player, key) {
  let c = spookCharters(player.server).getCompound(key)
  if (!c || !c.contains('x') || spookDim(player.level) != c.getString('dim')) return false
  let dx = player.x - c.getInt('x'), dz = player.z - c.getInt('z')
  return dx * dx + dz * dz < SPOOK_RANGE * SPOOK_RANGE
}

function spookGiveCharter(player, key) {
  let given = player.persistentData.getCompound('spookChartersGiven')
  if (given.getBoolean(key)) return
  let id = 'spooktacular:charter_' + key
  if (player.inventory.find(id) >= 0) return   // already carrying one
  player.give(Item.of(id))
  given.putBoolean(key, true)
  player.persistentData.put('spookChartersGiven', given)
  player.tell(Text.gold('You received the Town Charter for ' + global.SPOOK_CHARTERS[key] + '.'))
}

function spookCharterTask(event, key) {
  event.checkTimer = 100   // every 5 seconds per player
  event.maxProgress = 100
  event.check = (task, player) => {
    let c = spookCharters(player.server).getCompound(key)
    if (!c || !c.contains('x')) { spookGiveCharter(player, key); return }
    if (!spookNear(player, key)) return
    let pct = spookScanSlice(player.server, key)
    if (pct < 0) return
    task.progress = pct >= SPOOK_MATCH ? 100 : pct
  }
}

// Q-HT07: villagers living in town, counted around the Colossal Scarecrow's Charter.
function spookVillagerTask(event, need) {
  event.checkTimer = 200
  event.maxProgress = need
  event.check = (task, player) => {
    let c = spookCharters(player.server).getCompound('scarecrow')
    if (!c || !c.contains('x')) return
    let level = player.server.getLevel(c.getString('dim'))
    if (!level) return
    let x = c.getInt('x'), y = c.getInt('y'), z = c.getInt('z')
    let n = level.getEntitiesWithin(AABB.of(x - 96, y - 32, z - 96, x + 96, y + 48, z + 96)).filter(e => e.type == 'minecraft:villager').length
    task.progress = Math.min(need, n)
  }
}

// Q-HT01: stand inside a box (the theatre).
function spookLocationTask(event, box) {
  event.checkTimer = 40
  event.maxProgress = 1
  event.check = (task, player) => {
    if (spookDim(player.level) != box.dim) return
    if (player.x >= box.x1 && player.x <= box.x2 && player.y >= box.y1 && player.y <= box.y2 && player.z >= box.z1 && player.z <= box.z2) task.progress = 1
  }
}

// Chapter 8: wake up in a dreamspace. Dreamshift gives every visit its own dimension,
// "dreamshift:instances/dreamshift/<world>/<visit id>", so the plain dimension task can't match it.
function spookDreamTask(event, world) {
  event.checkTimer = 20
  event.maxProgress = 1
  event.check = (task, player) => {
    let d = spookDim(player.level)
    if (d == 'dreamshift:' + world || d.indexOf('dreamshift:instances/dreamshift/' + world + '/') == 0) task.progress = 1
  }
}

Object.keys(global.SPOOK_QUEST_DATA.customTasks).forEach(taskId => {
  let kind = global.SPOOK_QUEST_DATA.customTasks[taskId]
  FTBQuestsEvents.customTask(taskId, event => {
    if (kind.startsWith('charter:')) spookCharterTask(event, kind.substring(8))
    else if (kind.startsWith('villagers_in_town:')) spookVillagerTask(event, parseInt(kind.substring(18)))
    else if (kind.startsWith('location:')) spookLocationTask(event, global.SPOOK_QUEST_DATA.locations[kind.substring(9)])
    else if (kind.startsWith('dream:')) spookDreamTask(event, kind.substring(6))
  })
})

// Right-click a Charter: progress. Sneak + right-click: briefly mark wrong or missing blocks.
// A right-click with no result yet runs the whole check at once, so it answers even before the quest unlocks.
BlockEvents.rightClicked(event => {
  let key = spookCharterKey(event.block.id)
  if (!key || String(event.hand) != 'MAIN_HAND') return
  spookCharterClick(event, key)
  event.cancel()   // KubeJS 6: cancel() ends the handler at once, so it must come last
})

function spookCharterClick(event, key) {
  let name = global.SPOOK_CHARTERS[key]
  let c = spookCharters(event.server).getCompound(key)
  if (!c || !c.contains('x') || c.getInt('x') != event.block.x || c.getInt('y') != event.block.y || c.getInt('z') != event.block.z) {
    event.player.tell(Text.gray(name + ': this Charter is not the registered one. Break it and place it again.'))
    return
  }
  let s = spookScan[key]
  if (!s || s.pct < 0) {
    let pct = -1, guard = 0
    while (pct < 0 && guard++ < 200) pct = spookScanSlice(event.server, key)
    s = spookScan[key]
    if (pct < 0 || !s) {
      event.player.tell(Text.gray(name + ': could not check yet. Stay nearby and try again.'))
      return
    }
  }
  if (event.player.crouching) {
    let spots = (s.lastWrong || []).slice(0, 60)
    // one dot per block, redrawn every half second for 8 seconds so there's time to walk over and look
    let server = event.server, who = event.player.username
    spookTimes(16, n => server.scheduleInTicks(n * 10, () => {
      spots.forEach(p => server.runCommandSilent('particle minecraft:dust 1 0.4 0 1.2 ' + (p[0] + 0.5) + ' ' + (p[1] + 0.5) + ' ' + (p[2] + 0.5) + ' 0 0 0 0 1 force ' + who))
    }))
    event.player.tell(Text.gold(name + ': showing ' + spots.length + ' wrong or missing blocks for 8 seconds.'))
  } else {
    event.player.tell(Text.gold(name + ': ' + s.pct + '% matches the blueprint').append(Text.gray(' (' + s.lastOff + ' blocks off, ' + SPOOK_MATCH + '% needed). The quest counts it once the quest is unlocked.')))
  }
}
